import openpyxlimport osimport mysql.connectorimport configfrom tools import Toolsclass Saver:    def __init__(self):        self.__tools_obj = Tools()        self.__logger = Tools().get_logger("./")    def logging(self, text):        self.__logger.info(text)    ''' SAVE INTO DB '''    def saver(self, result_dict):        try:            conexion = mysql.connector.connect(                host='localhost',                user='root',                password='123456789',                database='seek_crawler'            )            cursor = conexion.cursor()            # Preparar la consulta de inserción            insert_query = """                INSERT INTO jobs (titulo, telefono_1, telefono_2, telefono_3, resumen, tipo, salario, ubicacion, email_1, email_2, email_3, link)                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)                """            # Obtener los valores del result_dict            for result in result_dict:                values = (                    result['titulo'],                    result['telefono_1'],                    result['telefono_2'],                    result['telefono_3'],                    result['resumen'],                    result['tipo'],                    result['salario'],                    result['ubicacion'],                    result['email_1'],                    result['email_2'],                    result['email_3'],                    result['link']                )                # Ejecutar la consulta de inserción                cursor.execute(insert_query, values)                # Hacer commit para guardar los cambios en la base de datos                conexion.commit()            # Cerrar el cursor y la conexión            cursor.close()            conexion.close()        except mysql.connector.Error as error:            print("Error al guardar datos en la base de datos:", error)        if conexion.is_connected():            cursor.close()            conexion.close()    '''def saver(self, result_dict):        try:            for result in result_dict:                                    headers = list(result.keys())                    # If the file doesn't exist, create a new workbook and add a new worksheet                    if not os.path.exists(config.keywords + '.xlsx'):                        workbook = openpyxl.Workbook()                        worksheet = workbook.active                        worksheet.append(headers)                        # If the file exists, open it and add the results to the existing worksheet                    else:                        workbook = openpyxl.load_workbook(config.keywords + '.xlsx')                        worksheet = workbook.active                    # Get the values from the result dictionary and add them as a new row in the worksheet                    row = [value for value in result.values()]                    self.logging('Saving in excel')                    worksheet.append(row)                    # Save the workbook to the file                    workbook.save(config.keywords + '.xlsx')                        except Exception as e:            self.logging('ERROR in saver() - {}'.format(e))'''